head.script:
scwin.onpageload = function() {
    inputCalendar1.setValue(99991212);
    inputCalendar2.setValue(99991212);
};
scwin.onpageunload = function() {};
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById($p.id + 'inputCalendar1_calendar_selectbox_year_label').innerText == '9999년';
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar1_img').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_last_year').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_next_month')[0].click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
